<style>.ca-page{color:#203346}.ca-head{display:flex;align-items:center;justify-content:space-between;gap:15px;margin-bottom:20px}.ca-head p{margin:4px 0 0;color:#748390;font-size:13px}.ca-head h3,.ca-head h4{margin:0;font-weight:700}.ca-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-bottom:18px}.ca-stats>div{background:white;border:1px solid #dce6ee;border-radius:10px;padding:18px}.ca-stats small,.ca-stats strong{display:block}.ca-stats strong{font-size:23px;margin-top:5px}.ca-stats>div:last-child{background:#ecf7f1}#ca-dialog{width:min(700px,94vw);border:0;border-radius:12px;padding:24px;max-height:92dvh;overflow:auto}#ca-dialog::backdrop{background:#142d466b}@media(max-width:600px){.ca-stats{grid-template-columns:1fr}.ca-head{align-items:flex-start}}.ca-week-tabs{display:flex;gap:8px;flex-wrap:wrap}.ca-person{background:white;border:1px solid #dce6ee;margin-bottom:12px;padding:16px}.ca-person-head{display:flex;align-items:center;justify-content:space-between;gap:14px}.ca-week-summary{display:flex;gap:18px;flex-wrap:wrap;margin:14px 0;font-size:13px}.ca-person summary{cursor:pointer;font-size:13px;color:#456}.ca-week-tabs .active{background:#203346;color:white}@media(max-width:600px){.ca-person-head{flex-wrap:wrap}}.ca-guide{display:flex;gap:12px;flex-wrap:wrap;padding:12px;background:#edf3f6;margin-bottom:14px;font-size:12px}.ca-balance-line{display:flex;gap:12px;justify-content:space-between;background:#f3f7fa;padding:10px;margin-top:12px;font-size:13px}.ca-week-summary span{background:#f6f8fa;border:1px solid #dce6ee;padding:8px 12px}.ca-history-dialog{width:min(1200px,96vw);max-height:92dvh;overflow:auto;border:1px solid #ccd8df;padding:24px}.ca-history-dialog::backdrop{background:#142d4677}</style>
<script>
(function(){const dialog=document.getElementById('ca-dialog'),form=document.getElementById('ca-form'),rows={{ \Illuminate\Support\Js::from($editRows) }},store={{ \Illuminate\Support\Js::from(route('contractor-advances.store')) }};
document.getElementById('ca-add').addEventListener('click',()=>openBatch(''));document.getElementById('ca-close').addEventListener('click',()=>dialog.close());document.querySelectorAll('[data-ca-edit]').forEach(button=>button.addEventListener('click',()=>{const row=rows.find(r=>String(r.id)===button.dataset.caEdit);document.querySelectorAll('.ca-history-dialog[open]').forEach(d=>d.close());form.reset();for(const [key,value] of Object.entries(row))if(form.elements.namedItem(key))form.elements.namedItem(key).value=value??'';form.action=store+'/'+row.id;form.elements._method.value='PUT';document.getElementById('ca-title').textContent='Edit Contractor Advance';dialog.showModal();}));document.querySelectorAll('[data-ca-history]').forEach(btn=>btn.addEventListener('click',()=>document.getElementById(btn.dataset.caHistory).showModal()));document.querySelectorAll('[data-history-close]').forEach(btn=>btn.addEventListener('click',()=>btn.closest('dialog').close()));let selectedWeek={{ \Illuminate\Support\Js::from($week?(string)$week:'') }};
function refresh(){const q=document.getElementById('ca-search').value.toLowerCase().trim();let total=0;document.querySelectorAll('.ca-person').forEach(person=>{const amounts=JSON.parse(person.dataset.weekAmounts),amount=Object.entries(amounts).reduce((sum,[w,n])=>sum+(!selectedWeek||w===selectedWeek?Number(n):0),0);person.hidden=!person.dataset.caName.includes(q);if(!person.hidden)total+=amount;person.querySelector('.ca-period-label').textContent=(selectedWeek?'Week '+selectedWeek+' — ':'')+{{ \Illuminate\Support\Js::from($month->format('F Y')) }}+' cash given';person.querySelector('.ca-person-total').textContent='Rs '+(amount/100).toLocaleString('en-PK',{minimumFractionDigits:2,maximumFractionDigits:2});let count=0;person.querySelectorAll('tr[data-week]').forEach(row=>{row.hidden=!!selectedWeek&&row.dataset.week!==selectedWeek;if(!row.hidden)count++;});person.querySelector('.ca-empty').hidden=count>0;person.querySelectorAll('[data-week-summary]').forEach(el=>el.hidden=!!selectedWeek&&el.dataset.weekSummary!==selectedWeek);});document.getElementById('ca-visible-total').textContent=(selectedWeek?'Week '+selectedWeek:'All Weeks')+' — Visible Cash Given: Rs '+(total/100).toLocaleString('en-PK',{minimumFractionDigits:2,maximumFractionDigits:2});document.querySelectorAll('[data-week-filter]').forEach(btn=>btn.classList.toggle('active',btn.dataset.weekFilter===selectedWeek));}
document.querySelectorAll('[data-week-filter]').forEach(btn=>btn.addEventListener('click',()=>{selectedWeek=btn.dataset.weekFilter;const url=new URL(location.href);url.searchParams.set('month',{{ \Illuminate\Support\Js::from($month->format('Y-m')) }});selectedWeek?url.searchParams.set('week',selectedWeek):url.searchParams.delete('week');history.replaceState(null,'',url);refresh();}));
document.getElementById('ca-search').addEventListener('input',refresh);
document.getElementById('ca-month-form').addEventListener('change',function(){this.requestSubmit();});
document.querySelectorAll('[data-ca-add-person]').forEach(btn=>btn.addEventListener('click',()=>openBatch(btn.dataset.caAddPerson)));
const batchDialog=document.getElementById('ca-batch-dialog'),batchForm=document.getElementById('ca-batch-form'),weekSelect=document.getElementById('ca-batch-week'),dateInput=document.getElementById('ca-batch-date'),amountInput=document.getElementById('ca-batch-amount'),remarksInput=document.getElementById('ca-batch-remarks');let queue=[],editing=-1;const monthKey={{ \Illuminate\Support\Js::from($month->format('Y-m')) }};
function uuid(){const bytes=crypto.getRandomValues(new Uint8Array(16));bytes[6]=(bytes[6]&15)|64;bytes[8]=(bytes[8]&63)|128;const h=Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');return h.slice(0,8)+'-'+h.slice(8,12)+'-'+h.slice(12,16)+'-'+h.slice(16,20)+'-'+h.slice(20);}
function defaultDate(){dateInput.value=monthKey+'-'+String((Number(weekSelect.value)-1)*7+1).padStart(2,'0');}
function openBatch(person){if(queue.length&&!confirm('Discard unsaved queued advances?'))return;queue=[];editing=-1;batchForm.reset();batchForm.elements.contractor_id.value=person;weekSelect.value='1';defaultDate();renderQueue();batchDialog.showModal();}
let queuePerson='';batchForm.elements.contractor_id.addEventListener('focus',()=>queuePerson=batchForm.elements.contractor_id.value);batchForm.elements.contractor_id.addEventListener('change',()=>{if(queue.length){if(!confirm('Discard queued advances before changing contractor?')){batchForm.elements.contractor_id.value=queuePerson;return;}queue=[];editing=-1;renderQueue();}queuePerson=batchForm.elements.contractor_id.value;});weekSelect.addEventListener('change',defaultDate);document.getElementById('ca-batch-close').addEventListener('click',()=>{if(!queue.length||confirm('Close without saving queued advances?'))batchDialog.close();});batchDialog.addEventListener('cancel',e=>{if(queue.length&&!confirm('Close without saving queued advances?'))e.preventDefault();});
function renderQueue(){const body=document.getElementById('ca-queue-rows'),inputs=document.getElementById('ca-queue-inputs');body.replaceChildren();inputs.replaceChildren();let total=0;queue.forEach((r,i)=>{total+=Math.round(Number(r.amount)*100);const tr=document.createElement('tr');['Week '+String(r.week).padStart(2,'0'),r.advance_date,'Rs '+Number(r.amount).toFixed(2),r.remarks].forEach(v=>{const td=document.createElement('td');td.textContent=v;tr.append(td);});const td=document.createElement('td');[['Edit',()=>{editing=i;weekSelect.value=r.week;dateInput.value=r.advance_date;amountInput.value=r.amount;remarksInput.value=r.remarks;document.getElementById('ca-queue-add').textContent='Update Entry';}],['Remove',()=>{queue.splice(i,1);editing=-1;document.getElementById('ca-queue-add').textContent='+ Add';renderQueue();}]].forEach(([label,action])=>{const btn=document.createElement('button');btn.type='button';btn.className='btn btn-sm btn-outline-dark me-1';btn.textContent=label;btn.addEventListener('click',action);td.append(btn);});tr.append(td);body.append(tr);Object.entries(r).forEach(([k,v])=>{const input=document.createElement('input');input.type='hidden';input.name='entries['+i+']['+k+']';input.value=v;inputs.append(input);});});document.getElementById('ca-queue-total').textContent='Queued Total: Rs '+(total/100).toFixed(2);document.getElementById('ca-save-all').disabled=!queue.length;}
document.getElementById('ca-queue-add').addEventListener('click',()=>{const week=Number(weekSelect.value),date=dateInput.value,amount=amountInput.value,error=document.getElementById('ca-queue-error');error.textContent='';if(!batchForm.elements.contractor_id.value||!/^\d{1,11}(\.\d{1,2})?$/.test(amount)||Number(amount)<=0||date.slice(0,7)!==monthKey||Math.ceil(Number(date.slice(8,10))/7)!==week||date>dateInput.max){error.textContent='Select contractor, valid positive amount and an actual payment date within this week (not in the future).';return;}const r={week,advance_date:date,amount,remarks:remarksInput.value,submission_key:editing>=0?queue[editing].submission_key:uuid()};if(editing>=0)queue[editing]=r;else queue.push(r);editing=-1;document.getElementById('ca-queue-add').textContent='+ Add';weekSelect.value=String(Math.min(week+1,weekSelect.options.length));defaultDate();amountInput.value='';remarksInput.value='';renderQueue();amountInput.focus();});
batchForm.addEventListener('submit',e=>{if(!queue.length){e.preventDefault();return;}document.getElementById('ca-save-all').disabled=true;});
const weekInfo=document.createElement('small');weekInfo.className='text-muted d-block mt-1';form.elements.advance_date.after(weekInfo);function updateWeek(){const date=form.elements.advance_date.value;weekInfo.textContent=date?'Payment month: '+date.slice(0,7)+' · Week '+Math.ceil(Number(date.slice(8,10))/7):'';}form.elements.advance_date.addEventListener('change',updateWeek);refresh();updateWeek();
document.querySelectorAll('[data-ca-edit]').forEach(btn=>btn.addEventListener('click',updateWeek));
@if($errors->any())
@if(old('entries')) queue={{ \Illuminate\Support\Js::from(old('entries')) }};batchForm.elements.contractor_id.value={{ \Illuminate\Support\Js::from(old('contractor_id')) }};renderQueue();defaultDate();batchDialog.showModal();
@else dialog.showModal(); @endif
@endif
form.addEventListener('submit',()=>{form.querySelector('button[type=submit]').disabled=true;});})();
</script>
